@List.idRun_forIn_yield_eq_foldl : ∀ {α : Type u_1} {β : Type u_2} (l : List α) (f : α → β → Id β) (init : β),
  (forIn l init fun a b => ForInStep.yield <$> f a b).run = List.foldl (fun b a => (f a b).run) init l
@Id.run_pure : ∀ {α : Type u_1} (a : α), (pure a).run = a
@Id.run_bind : ∀ {α β : Type u_1} (x : Id α) (f : α → Id β), (x >>= f).run = (f x.run).run
def dupImp : String → String :=
fun s =>
  (have out := "";
    bind
      (forIn s.toList out fun c r =>
        have out := r;
        have out := out.push c;
        have out := out.push c;
        bind (pure PUnit.unit) fun x => pure (ForInStep.yield out))
      fun r =>
      have out := r;
      pure out).run

